#!/bin/sh
# sandbox-ai-mcp toolchain rust: rustc's link line for zig cc (the toolchain cc). zig links with its own lld and brings
# its own unwinder: -fuse-ld=lld and rustc's gcc-ld folder go, -lgcc_s becomes -lunwind.
# -Wl,--fix-cortex-a53-*: rustc asks for these erratum fixes on aarch64; zig cc refuses them ("unsupported
# linker arg"), so they go: only Cortex-A53 cores of the first revisions (r0p0-r0p4) need them.
n=$#
while [ "$n" -gt 0 ]; do
  a=$1
  shift
  n=$((n - 1))
  case $a in
    -fuse-ld=*) ;;
    -B*/gcc-ld) ;;
    -Wl,--fix-cortex-a53-*) ;;
    -lgcc_s) set -- "$@" -lunwind ;;
    *) set -- "$@" "$a" ;;
  esac
done
exec cc "$@"
